(function (window, document) {
	'use strict';

	var config = window.GoVergeSearch || {};
	var endpoint = String(config.endpoint || '');
	var minChars = Number(config.minChars) || 3;
	var uid = 0;

	function escapeHtml(value) {
		return String(value || '').replace(/[&<>'"]/g, function (char) {
			return { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[char];
		});
	}

	function debounce(fn, wait) {
		var timer = null;
		return function () {
			var args = arguments;
			clearTimeout(timer);
			timer = setTimeout(function () { fn.apply(null, args); }, wait);
		};
	}

	function initForm(form) {
		var input = form.querySelector('input[type="search"][name="s"]');
		if (!input || !endpoint || input.dataset.goEnhancedSearch === '1') {
			return;
		}
		input.dataset.goEnhancedSearch = '1';

		var wrapper = document.createElement('div');
		wrapper.className = 'go-search-suggest-wrap';
		input.parentNode.insertBefore(wrapper, input);
		wrapper.appendChild(input);

		var panel = document.createElement('div');
		panel.className = 'go-search-suggestions';
		panel.hidden = true;
		panel.id = 'go-search-suggestions-' + (++uid);
		panel.setAttribute('role', 'listbox');
		wrapper.appendChild(panel);
		input.setAttribute('aria-controls', panel.id);
		input.setAttribute('aria-expanded', 'false');
		input.setAttribute('autocomplete', 'off');

		var controller = null;
		var generation = 0;
		var cache = new Map();
		var activeIndex = -1;
		var items = [];

		function closePanel() {
			generation++;
			if (controller) { controller.abort(); }
			panel.hidden = true;
			panel.innerHTML = '';
			input.setAttribute('aria-expanded', 'false');
			input.removeAttribute('aria-activedescendant');
			items = [];
			activeIndex = -1;
		}

		function setActive(index) {
			items = Array.prototype.slice.call(panel.querySelectorAll('[role="option"]'));
			if (!items.length) {
				activeIndex = -1;
				return;
			}
			activeIndex = (index + items.length) % items.length;
			items.forEach(function (item, i) {
				item.classList.toggle('is-active', i === activeIndex);
				item.setAttribute('aria-selected', i === activeIndex ? 'true' : 'false');
			});
			input.setAttribute('aria-activedescendant', items[activeIndex].id);
			items[activeIndex].scrollIntoView({ block: 'nearest' });
		}

		function render(results) {
			panel.innerHTML = '';
			if (!results || !results.length) {
				panel.innerHTML = '<div class="go-search-suggestions__empty">Nenhum resultado rápido</div>';
				panel.hidden = false;
				input.setAttribute('aria-expanded', 'true');
				return;
			}

			var list = document.createElement('div');
			list.className = 'go-search-suggestions__list';
			results.forEach(function (result, index) {
				var link = document.createElement('a');
				link.href = result.url || '#';
				link.className = 'go-search-suggestion';
				link.setAttribute('role', 'option');
				link.setAttribute('aria-selected', 'false');
				link.id = panel.id + '-item-' + index;
				var media = result.image_url ? '<span class="go-search-suggestion__media"><img src="' + escapeHtml(result.image_url) + '" alt="" width="48" height="48" loading="lazy" decoding="async"></span>' : '<span class="go-search-suggestion__media go-search-suggestion__media--empty" aria-hidden="true"></span>';
				link.innerHTML = media + '<span class="go-search-suggestion__copy"><strong>' + escapeHtml(result.title || '') + '</strong><span>' + escapeHtml(result.type || '') + '</span></span><span class="go-search-suggestion__arrow" aria-hidden="true">→</span>';
				list.appendChild(link);
			});
			panel.appendChild(list);
			panel.hidden = false;
			input.setAttribute('aria-expanded', 'true');
			items = Array.prototype.slice.call(panel.querySelectorAll('[role="option"]'));
			activeIndex = -1;
		}

		var search = debounce(function (requestedGeneration) {
			if (requestedGeneration !== generation || document.activeElement !== input) { return; }
			var query = input.value.trim();
			if (query.length < minChars || query.length > 80) {
				closePanel();
				return;
			}
			if (controller && controller.abort) {
				controller.abort();
			}
			if (cache.has(query)) { render(cache.get(query)); return; }
			controller = 'AbortController' in window ? new AbortController() : null;
			panel.hidden = false;
			panel.innerHTML = '<div class="go-search-suggestions__loading">Buscando…</div>';
			input.setAttribute('aria-expanded', 'true');

			fetch(endpoint + '?q=' + encodeURIComponent(query) + '&limit=8', {
				credentials: 'same-origin',
				signal: controller ? controller.signal : undefined
			})
				.then(function (response) {
					if (!response.ok) { throw new Error('search'); }
					return response.json();
				})
				.then(function (results) {
					if (requestedGeneration !== generation || query !== input.value.trim() || document.activeElement !== input) { return; }
					if (cache.size >= 30) { cache.delete(cache.keys().next().value); }
					cache.set(query, results);
					render(results);
				})
				.catch(function (error) {
					if (requestedGeneration !== generation) { return; }
					if (error && error.name === 'AbortError') { return; }
					closePanel();
				});
		}, 350);

		function queueSearch() { closePanel(); search(generation); }

		input.addEventListener('input', queueSearch);
		input.addEventListener('focus', function () {
			if (input.value.trim().length >= minChars) { queueSearch(); }
		});
		input.addEventListener('keydown', function (event) {
			if (panel.hidden) { return; }
			if (event.key === 'ArrowDown') {
				event.preventDefault();
				setActive(activeIndex + 1);
			} else if (event.key === 'ArrowUp') {
				event.preventDefault();
				setActive(activeIndex - 1);
			} else if (event.key === 'Escape') {
				closePanel();
			} else if (event.key === 'Enter' && activeIndex >= 0 && items[activeIndex]) {
				event.preventDefault();
				window.location.href = items[activeIndex].href;
			}
		});

		document.addEventListener('click', function (event) {
			if (!form.contains(event.target)) {
				closePanel();
			}
		});
	}

	function init() {
		document.querySelectorAll('form[role="search"], form.go-search-page__form').forEach(initForm);
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})(window, document);
